const Services = () => {
  // const dummyServices = [
  //   { service_name: "Cash Withdrawal", slug: "CW", status: true },
  //   { service_name: "Balance Enquiry", slug: "BE", status: true },
  //   { service_name: "Mini Statement", slug: "MS", status: false },
  // ];

  const { service } = useParams();

  const [allServices, setAllServices] = useState([]);

  const { selectedAEPSProvider } = useAEPSService();

  const getAllServices = async () => {
    try {
      let res = await getAepsservies(selectedAEPSProvider);
      if (res?.data?.statusCode === 200) {
        setAllServices(res?.data?.data || []);
      } else {
        setAllServices([]);
      }
    } catch (error) {}
  };

  const getCashDeposite = async () => {
    try {
      let res = await getAepsCashDeposite(selectedAEPSProvider);
      if (res?.data?.statusCode === 200) {
        setAllServices(res?.data?.data || []);
      } else {
        setAllServices([]);
      }
    } catch (error) {}
  };
  useEffect(() => {
    if (!service) {
      getAllServices();
    }

    if (service === "cash-deposit") {
      getCashDeposite();
    }
  }, [selectedAEPSProvider]);

  const serviceComponentMap = {
    CW: CashWithdrawalWithPin,
    BE: BalanceEnquiryWithPin,
    MS: MiniStatementWithPin,
    CD: CashDepositeWithPin,
    // aadhaar_pay: AadhaarPay,
  };

  const [selectedService, setSelectedService] = useState(null);

  useEffect(() => {
    if (allServices?.length > 0 && !selectedService) {
      // Default to Cash Withdrawal ("CW") if available and active, otherwise the first active service
      const defaultService =
        allServices.find((s) => s.slug === "CW" && s.status) ||
        allServices.find((s) => s.status) ||
        allServices[0];
      if (defaultService) {
        setSelectedService(defaultService.slug);
      }
    }
  }, [allServices, selectedService]);

  const handleServiceClick = (service) => {
    if (!service.status) {
      toast.error(`${service.service_name} is not active.`);
      return;
    }
    setSelectedService(service.slug);
  };

  const SelectedComponent = selectedService
    ? serviceComponentMap[selectedService]
    : null;

  return (
    <CustomBox>
      <Box p={2}>
        <Typography
          variant="h6"
          mb={2.5}
          fontWeight="700"
          color="var(--bs-primary2)"
          sx={{
            textAlign: "center",
          }}
        >
          AEPS Services
        </Typography>

        {/* Top Service Tabs */}
        <Grid container spacing={2} justifyContent="center" sx={{ mb: 3 }}>
          {allServices?.map((service) => {
            const isSelected = selectedService === service.slug;
            return (
              <Grid item xs={12} sm={4} md={3} key={service.slug}>
                <Card
                  onClick={() => handleServiceClick(service)}
                  sx={{
                    borderRadius: "16px",
                    cursor: service.status ? "pointer" : "not-allowed",
                    opacity: service.status ? 1 : 0.6,
                    background: isSelected
                      ? "linear-gradient(135deg, #193968 0%, #255494 100%)"
                      : "var(--bs-primary3, #ffffff)",
                    color: isSelected ? "#ffffff" : "var(--bs-primary2, #193968)",
                    boxShadow: isSelected
                      ? "0 8px 24px rgba(25, 57, 104, 0.28)"
                      : "0 4px 14px rgba(0,0,0,0.05)",
                    border: isSelected
                      ? "2px solid #193968"
                      : service.status
                      ? "1px solid #e0e6ef"
                      : "1px dashed #cfd6df",
                    transition: "all 0.25s ease-in-out",
                    transform: isSelected ? "scale(1.02)" : "scale(1)",
                    "&:hover": {
                      transform: service.status ? "scale(1.03)" : "none",
                      boxShadow: "0 8px 20px rgba(0,0,0,0.12)",
                    },
                  }}
                >
                  <CardContent sx={{ textAlign: "center", py: 2.2, px: 2 }}>
                    <Typography
                      variant="subtitle1"
                      fontWeight={isSelected ? 800 : 600}
                      color={isSelected ? "#ffffff" : "var(--bs-primary2)"}
                      component={"span"}
                    >
                      {service.service_name}
                    </Typography>
                    {!service.status && (
                      <Typography
                        fontSize={10}
                        sx={{ ml: 1, display: "block" }}
                        color="error"
                      >
                        Not Active
                      </Typography>
                    )}
                  </CardContent>
                </Card>
              </Grid>
            );
          })}
        </Grid>

        {/* Selected Service Form rendered immediately below on the same page */}
        {SelectedComponent && (
          <Box sx={{ mt: 1 }}>
            <SelectedComponent />
          </Box>
        )}
      </Box>
    </CustomBox>
  );
};

const AEPSOnboarding = ({ ensureLocation }) => {
  const [open, setOpen] = useState(false);
  const [otp, setOtp] = useState("");
  const {
    setAepsGlobalLoader,
    setAepsCurrentPage,
    selectedAEPSProvider,
    setTriggerAuthApi,
  } = useAEPSService();

  const handleOpen = () => setOpen(true);
  const handleClose = () => {
    setOpen(false);
    setOtp("");
  };

  const otpSend = async () => {
    const { latitude, longitude } = await ensureLocation();

    setAepsGlobalLoader(true);
    let body = {
      bank: selectedAEPSProvider,
      latitude: latitude,
      longitude: longitude,
    };
    try {
      let res = await getAepsOnboarding(body);
      if (res?.data?.statusCode === "007") {
        handleOpen();
      }
      toastMessage(res?.data?.error, res?.data?.message);
    } catch (error) {
    } finally {
      setAepsGlobalLoader(false);
    }
  };

  const handleVerify = async () => {
    setAepsGlobalLoader(true);
    const clone = {
      mobile: window.localStorage.getItem("regisNumber").slice(-10),
      otp: otp,
    };
    try {
      const res = await verifybank3otp(clone);
      if (res?.data?.statusCode === 200) {
        setAepsCurrentPage("");
        setTriggerAuthApi((pre) => !pre);
        // setCurrentPage('money-transfer')
        // handleClose();
      }
      toastMessage(res?.data?.error, res?.data?.message);
    } catch (error) {
    } finally {
      setAepsGlobalLoader(false);
    }
  };

  return (
    <>
      <CustomBox>
        <Box display="flex" alignItems="center" gap={2} mb={2}>
          <Typography
            variant="body2"
            color="var(--bs-primary2)"
            fontWeight="bold"
            fontSize={18}
          >
            Service
          </Typography>
        </Box>
        <Typography
          variant="body2"
          color="var(--bs-primary2)"
          fontWeight="bold"
          fontSize={16}
        >
          Please complete your onboarding process by{" "}
          <Typography
            component={"span"}
            sx={{ cursor: "pointer", textDecoration: "underline" }}
            onClick={otpSend}
          >
            clicking here{" "}
          </Typography>
        </Typography>
      </CustomBox>

      <Dialog open={open} onClose={handleClose} maxWidth="xs" fullWidth>
        <DialogTitle sx={{ color: "var(--bs-primary2)" }}>
          OTP Verification
        </DialogTitle>
        <DialogContent>
          <Typography mb={2} sx={{ color: "var(--bs-primary2)" }}>
            Enter the 6-digit code sent to your mobile number.
          </Typography>

          <CustomTextField
            fullWidth
            label="Enter OTP"
            value={otp}
            onChange={(e) => {
              const onlyDigits = e.target.value.replace(/\D/g, "");
              if (onlyDigits.length <= 6) setOtp(onlyDigits);
            }}
            inputProps={{ maxLength: 6 }}
            autoFocus
          />
        </DialogContent>

        <DialogActions>
          <Button onClick={handleClose}>Cancel</Button>
          <Button
            onClick={handleVerify}
            sx={{
              borderColor: "var(--bs-primary1)",
              backgroundColor: "var(--bs-primary1)",
              color: "var(--bs-primary2)",
            }}
            variant="contained"
            disabled={otp.length < 6}
          >
            Verify
          </Button>
        </DialogActions>
      </Dialog>
    </>
  );
};

const AEPSOnboardingWithPin = withPinLocation(AEPSOnboarding);
const CheckDailyAuthWithPin = withPinLocation(CheckDailyAuth);

