/**
 * Aadhaar Face RD Service & Intent Helper
 * Target App: in.gov.uidai.facerd (Official UIDAI FaceRD App on Google Play)
 * Action: in.gov.uidai.rdservice.face.CAPTURE
 */

export const FACE_RD_PACKAGE = "in.gov.uidai.facerd";
export const FACE_RD_PLAYSTORE_URL =
  "https://play.google.com/store/apps/details?id=in.gov.uidai.facerd";

/**
 * Check if the current browser environment is running on an Android mobile device.
 */
export const isAndroidDevice = () => {
  if (typeof navigator === "undefined") return false;
  return /Android/i.test(navigator.userAgent || navigator.vendor || window.opera);
};

/**
 * Build standard UIDAI / InstantPay Face PidOptions XML.
 * @param {boolean} isKyc - False for Daily 2FA Auth, True for eKYC Onboarding
 * @param {string} wadh - Optional WADH hash for KYC
 */
export const buildFacePidOptions = (isKyc = false, wadh = "") => {
  const txnId = Date.now().toString();
  const wadhAttr = wadh ? `wadh="${wadh}"` : 'wadh=""';

  return `<?xml version="1.0" encoding="UTF-8"?>
<PidOptions ver="1.0" env="P">
   <Opts fCount="0" fType="2" iCount="1" iType="2" pCount="0" pType="0" format="0" pidVer="2.0" timeout="20000" otp="" posh="" ${wadhAttr} />
   <CustOpts>
      <Param name="txnId" value="${txnId}"/>
      <Param name="purpose" value="auth"/>
      <Param name="language" value="en"/>
   </CustOpts>
</PidOptions>`.trim();
};

/**
 * Launch the official UIDAI Face RD App on Android via Android Intent URI.
 * If the app is not installed, it falls back to the Google Play Store.
 */
export const launchFaceRdCapture = (xmlPidOptions) => {
  if (!isAndroidDevice()) {
    return {
      success: false,
      isMobile: false,
      message: "Face RD is supported on Android devices with camera.",
    };
  }

  const encodedXml = encodeURIComponent(xmlPidOptions);
  // Standard Android Intent scheme for in.gov.uidai.facerd
  const intentUrl =
    `intent:#Intent;action=in.gov.uidai.rdservice.face.CAPTURE;category=android.intent.category.DEFAULT;package=${FACE_RD_PACKAGE};S.request=${encodedXml};end`;

  // Attempt to open the intent
  window.location.href = intentUrl;

  return {
    success: true,
    isMobile: true,
    message: "Launching Aadhaar FaceRD app...",
  };
};

/**
 * Convert standard XML string to Base64 data string for backend submission.
 */
export const convertXmlToBase64 = (xmlString) => {
  try {
    return window.btoa(unescape(encodeURIComponent(xmlString)));
  } catch (e) {
    return window.btoa(xmlString);
  }
};
